//! 🗃️ Retains the published presentation while its original seed, tick and retired children advance privately.
use super::{ToolRunPresentation,ToolRunPresentationBody,seed::ToolRunPresentationSeed,update::ToolRunPresentationUpdate};
use semio_framework_tool_run::{ToolRunIdentity,ToolRunState,ToolRunTick};
use semio_framework_tool_run_entities::{denied,local_step,route_fault,EntityComplete as Complete,EntityReply as Reply,ToolRunEntityEditGrant};
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedAllocationEffect,RetainedCloneProgress,RetainedCloneStep as Step,retained_clone_grant_admits},retirement::{RetireOwned,controlled::ControlledRetirement}};
use std::mem::{ManuallyDrop,size_of};

#[doc(hidden)]
pub struct State{seed:Option<ToolRunPresentationSeed>,published:Option<ToolRunPresentation>,update:Option<ToolRunPresentationUpdate>,candidate:Option<ToolRunPresentation>,displaced:Option<ToolRunPresentation>,seed_close:Option<ControlledRetirement<ToolRunPresentationSeed>>,update_close:Option<ControlledRetirement<ToolRunPresentationUpdate>>,displaced_close:Option<ControlledRetirement<ToolRunPresentation>>,pending_cancel:bool,route:Option<u8>,cancelled:bool}
semio_framework_value::artifact_retire_struct!(State{seed,published,update,candidate,displaced,seed_close,update_close,displaced_close,pending_cancel,route,cancelled});
fn item(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}}
pub struct ToolRunPresentationSlot{state:ManuallyDrop<State>,transferred:bool}
fn demands<T:RetireOwned>(owner:&ControlledRetirement<T>,body:usize)->Result<RetirementDemand,ValueError>{if owner.terminal_is_empty(){return Ok(RetirementDemand{copy_bytes:size_of::<Option<ControlledRetirement<T>>>(),depth:1,..Default::default()});}owner.selected_demand(body)}
impl ToolRunPresentationSlot{
 pub fn new(tool_id:String,identity:ToolRunIdentity,state:ToolRunState)->Self{Self{state:ManuallyDrop::new(State{seed:Some(ToolRunPresentationSeed::new(tool_id,identity,state)),published:None,update:None,candidate:None,displaced:None,seed_close:None,update_close:None,displaced_close:None,pending_cancel:false,route:None,cancelled:false}),transferred:false}}
 pub fn ready(&self)->bool{let s=&*self.state;!s.cancelled&&!s.pending_cancel&&s.published.is_some()&&s.seed.is_none()&&s.update.is_none()&&s.candidate.is_none()&&s.displaced.is_none()&&s.seed_close.is_none()&&s.update_close.is_none()&&s.displaced_close.is_none()}
 pub fn body(&self)->Option<&ToolRunPresentationBody>{self.state.published.as_ref().map(ToolRunPresentation::body)}
 pub fn identifier(&self)->&str{if let Some(body)=self.body(){body.tool_id.get()}else if let Some(candidate)=self.state.candidate.as_ref(){candidate.body().tool_id.get()}else{self.state.seed.as_ref().and_then(|seed|seed.original_identifier()).unwrap_or("")}}
 pub fn capture(&self,effect:&mut RetainedAllocationEffect<'_>)->Result<Option<(ToolRunPresentation,RetainedCloneProgress)>,ValueError>{if self.state.cancelled{return Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"closing original presentation cannot issue new captures"));}self.state.published.as_ref().map(|source|source.capture(effect)).transpose()}
 pub fn borrowed_view(&self,identity:ToolRunIdentity,state:ToolRunState)->Option<super::ToolRunView<'_>>{self.state.published.as_ref().map(|source|source.borrowed_view(identity,state))}
 pub fn capture_view(&self,identity:ToolRunIdentity,state:ToolRunState,effect:&mut RetainedAllocationEffect<'_>)->Result<Option<(super::ToolRunCapturedView,RetainedCloneProgress)>,ValueError>{if self.state.cancelled{return Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"closing original presentation cannot issue new context capture"));}self.state.published.as_ref().map(|source|source.capture_view(identity,state,effect)).transpose()}
 pub fn cancel_pending(&mut self){if self.state.update.is_some()||self.state.candidate.is_some(){self.state.pending_cancel=true;if let Some(update)=self.state.update.as_mut(){update.cancel();}}}
 pub fn cancel(&mut self){self.state.cancelled=true;if let Some(seed)=self.state.seed.as_mut(){seed.cancel();}if let Some(update)=self.state.update.as_mut(){update.cancel();}}
 pub fn tick_admission_demands()->RetirementDemand{{let mut demand=ToolRunPresentationUpdate::birth_demands();demand.copy_bytes+=ToolRunPresentation::capture_copy_bytes();demand}}
 pub fn begin_tick(&mut self,tick:ToolRunTick,end:u32,state:ToolRunState,rate:f32,conflicts:u32,effect:&mut RetainedAllocationEffect<'_>)->Result<((),RetainedCloneProgress),(ValueError,ToolRunTick)>{let grant=effect.grant();let quote=Self::tick_admission_demands();if !self.ready(){return Err((ValueError::literal(ValueRefusalKind::UnsupportedOwner,"original presentation slot still owns pending work"),tick));}if !semio_framework_value::retained_clone::retained_clone_grant_admits(grant,quote){return Err((ValueError::literal(ValueRefusalKind::OwnershipLimit,"original tick and presentation handoff are not funded"),tick));}let Some(original)=self.state.published.as_ref()else{return Err((ValueError::literal(ValueRefusalKind::InvariantViolated,"original presentation has no published body"),tick))};if tick.identity.id!=original.body().progress.identity.id{return Err((ValueError::literal(ValueRefusalKind::InvalidValue,"incoming original tick belongs to another run"),tick));}match original.capture(effect){Ok((capture,mut receipt))=>{let (update,birth)=ToolRunPresentationUpdate::admit(capture,tick,end,state,rate,conflicts,grant).unwrap_or_else(|_|panic!("original presentation update birth was fully preflighted"));self.state.update=Some(update);receipt.copied_bytes=quote.copy_bytes;receipt.retained_capacity_bytes=birth.retained_capacity_bytes;Ok(((),receipt))},Err(error)=>Err((error,tick))}}
 pub fn edit_capacity_bound(&self)->Result<usize,ValueError>{self.state.update.as_ref().map_or(Ok(0),ToolRunPresentationUpdate::edit_capacity_bound)}
 pub fn next_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{let s=&*self.state;if s.cancelled||self.ready(){return Ok(Default::default());}if let Some(owner)=s.seed_close.as_ref(){return demands(owner,body);}if let Some(owner)=s.update_close.as_ref(){return demands(owner,body);}if let Some(owner)=s.displaced_close.as_ref(){return demands(owner,body);}if s.displaced.is_some(){return Ok(RetirementDemand{copy_bytes:size_of::<ToolRunPresentation>(),depth:1,..Default::default()});}if s.pending_cancel&&s.candidate.is_some(){return Ok(RetirementDemand{copy_bytes:size_of::<ToolRunPresentation>(),depth:1,..Default::default()});}if let Some(seed)=s.seed.as_ref(){return if s.candidate.is_some(){Ok(RetirementDemand{copy_bytes:size_of::<ToolRunPresentationSeed>(),depth:1,..Default::default()})}else if seed.complete(){Ok(RetirementDemand{copy_bytes:size_of::<ToolRunPresentation>(),depth:1,..Default::default()})}else{seed.next_demands()};}if let Some(update)=s.update.as_ref(){return if s.pending_cancel||s.candidate.is_some(){Ok(RetirementDemand{copy_bytes:size_of::<ToolRunPresentationUpdate>(),depth:1,..Default::default()})}else if update.complete(){Ok(RetirementDemand{copy_bytes:size_of::<ToolRunPresentation>(),depth:1,..Default::default()})}else{update.next_demands(body)};}if s.candidate.is_some(){return Ok(RetirementDemand{copy_bytes:3*size_of::<ToolRunPresentation>(),depth:1,..Default::default()});}if s.pending_cancel{return Ok(RetirementDemand{copy_bytes:size_of::<bool>(),depth:1,..Default::default()});}Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"presentation slot has no original pending owner"))}
 pub fn advance_into<'r>(&mut self,body:usize,grant:ToolRunEntityEditGrant,effect:&mut RetainedAllocationEffect<'_>,reply:Reply<'r>)->Result<Complete<'r>,ValueError>{self.drive(body,grant,effect,reply,false)}
 pub fn recover_advance_into<'r>(&mut self,body:usize,grant:ToolRunEntityEditGrant,effect:&mut RetainedAllocationEffect<'_>,reply:Reply<'r>)->Result<Complete<'r>,ValueError>{self.drive(body,grant,effect,reply,true)}
 fn drive<'r>(&mut self,body:usize,grant:ToolRunEntityEditGrant,effect:&mut RetainedAllocationEffect<'_>,reply:Reply<'r>,recover:bool)->Result<Complete<'r>,ValueError>{
  if self.state.route.is_some()!=recover{return Err(route_fault("presentation slot changed its original recovery route"));}
  if !recover&&(self.state.cancelled||self.ready()||grant.retirement.maximum_items==0){return denied(reply);}
  let quote=if recover{Default::default()}else{self.next_demands(body)?};
  if !recover&&!retained_clone_grant_admits(grant.retirement,quote){return denied(reply);}
  let s=&mut*self.state;
  macro_rules! close {($field:ident,$key:expr)=>{if s.$field.is_some(){
   if s.$field.as_ref().is_some_and(|owner|owner.terminal_is_empty()){return local_step(effect,quote,1,reply,|_|{s.$field=None;Ok(item(quote))});}
   let owner=s.$field.as_mut().ok_or_else(||route_fault("presentation slot close owner is absent"))?;let mut scope=reply.scope(&mut s.route,$key)?;
   drop(if recover{owner.recover_step_into(body,effect,scope.borrow()?)}else{owner.step_into(body,effect,scope.borrow()?)}?);return Ok(scope.forwarded());
  }};}
  close!(seed_close,1);close!(update_close,2);close!(displaced_close,3);
  if s.displaced.is_some(){return local_step(effect,quote,1,reply,|_|{let displaced=s.displaced.take().unwrap();match ControlledRetirement::new(displaced){Ok(close)=>s.displaced_close=Some(close),Err((error,displaced))=>{s.displaced=Some(displaced);return Err(error);}}Ok(item(quote))});}
  if s.pending_cancel&&s.candidate.is_some(){return local_step(effect,quote,1,reply,|_|{s.displaced=s.candidate.take();Ok(item(quote))});}
  if s.seed.is_some(){
   if s.candidate.is_some(){return local_step(effect,quote,1,reply,|_|{let seed=s.seed.take().unwrap();match ControlledRetirement::new(seed){Ok(close)=>s.seed_close=Some(close),Err((error,seed))=>{s.seed=Some(seed);return Err(error);}}Ok(item(quote))});}
   if s.seed.as_ref().is_some_and(ToolRunPresentationSeed::complete){return local_step(effect,quote,1,reply,|effect|{let(output,progress)=s.seed.as_mut().unwrap().take_output(effect.grant())?.ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"presentation seed output absent"))?;s.candidate=Some(output);Ok(progress)});}
   return Ok(reply.complete(s.seed.as_mut().unwrap().advance(effect).map(Step::Progress).map_err(Into::into)));
  }
  if s.update.is_some(){
   if s.pending_cancel||s.candidate.is_some(){return local_step(effect,quote,1,reply,|_|{let update=s.update.take().unwrap();match ControlledRetirement::new(update){Ok(close)=>s.update_close=Some(close),Err((error,update))=>{s.update=Some(update);return Err(error);}}Ok(item(quote))});}
   if s.update.as_ref().is_some_and(ToolRunPresentationUpdate::complete){return local_step(effect,quote,1,reply,|effect|{let(output,progress)=s.update.as_mut().unwrap().take_output(effect.grant())?.ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"presentation update output absent"))?;s.candidate=Some(output);Ok(progress)});}
   let update=s.update.as_mut().unwrap();let mut scope=reply.scope(&mut s.route,4)?;drop(if recover{update.recover_advance_into(body,grant,effect,scope.borrow()?)}else{update.advance_into(body,grant,effect,scope.borrow()?)}?);return Ok(scope.forwarded());
  }
  if s.candidate.is_some(){return local_step(effect,quote,1,reply,|_|{let candidate=s.candidate.take().unwrap();s.displaced=s.published.replace(candidate);Ok(item(quote))});}
  if s.pending_cancel{return local_step(effect,quote,1,reply,|_|{s.pending_cancel=false;Ok(item(quote))});}
  Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"presentation slot cannot find its funded transition"))
 }
}
impl RetireOwned for ToolRunPresentationSlot{type RetirementCursor=<State as RetireOwned>::RetirementCursor;fn retirement_seed(mut self)->Self::RetirementCursor{self.transferred=true;unsafe{ManuallyDrop::take(&mut self.state)}.retirement_seed()}fn retirement_birth_bytes(&self)->Option<usize>{self.state.retirement_birth_bytes()}fn controlled_retirement_supported()->bool{true}fn retirement_element_copy_bytes()->usize{size_of::<Self>()}}
impl Drop for ToolRunPresentationSlot{fn drop(&mut self){if !self.transferred&&!std::thread::panicking(){panic!("original presentation slot requires controlled retirement")}}}
